#!/usr/bin/env python3
"""Condense a captured conversation JSONL into a readable trace.

usage: condense.py <file> [--text N] [--tool N] [--only-human] [--gaps SECS]
"""
import json, sys, argparse, datetime

ap = argparse.ArgumentParser()
ap.add_argument('path')
ap.add_argument('--text', type=int, default=1200)
ap.add_argument('--tool', type=int, default=160)
ap.add_argument('--only-human', action='store_true')
ap.add_argument('--gaps', type=float, default=0.0)
a = ap.parse_args()

def ts(e):
    t = e.get('timestamp') or ''
    try:
        return datetime.datetime.fromisoformat(t.replace('Z', '+00:00'))
    except Exception:
        return None

def clip(s, n):
    s = ' '.join(str(s).split())
    return s if len(s) <= n else s[:n] + f' …[{len(s)}c]'

prev = None
for line in open(a.path, encoding='utf-8'):
    line = line.strip()
    if not line:
        continue
    try:
        e = json.loads(line)
    except Exception:
        continue
    t = ts(e)
    stamp = t.strftime('%H:%M:%S') if t else '--:--:--'
    gap = ''
    if a.gaps and prev and t:
        d = (t - prev).total_seconds()
        if d >= a.gaps:
            gap = f'  <<gap {d:.0f}s>>'
    if t:
        prev = t
    msg = e.get('message') or {}
    role = msg.get('role') or e.get('type') or '?'
    content = msg.get('content')
    if isinstance(content, str):
        content = [{'type': 'text', 'text': content}]
    if not isinstance(content, list):
        continue
    for b in content:
        bt = b.get('type')
        if bt == 'text':
            txt = b.get('text', '').strip()
            if txt:
                print(f'[{stamp}] {role.upper()}: {clip(txt, a.text)}{gap}')
        elif bt == 'thinking':
            if not a.only_human:
                print(f'[{stamp}] think: {clip(b.get("thinking",""), a.tool)}')
        elif bt == 'tool_use':
            if a.only_human:
                continue
            inp = b.get('input') or {}
            keys = {k: clip(v, 200) for k, v in inp.items() if isinstance(v, (str, int, float))}
            print(f'[{stamp}] TOOL {b.get("name")} {clip(json.dumps(keys), a.tool)}{gap}')
        elif bt == 'tool_result':
            if a.only_human:
                continue
            c = b.get('content')
            if isinstance(c, list):
                c = ' '.join(x.get('text', '') for x in c if isinstance(x, dict))
            err = ' ERR' if b.get('is_error') else ''
            print(f'[{stamp}]   res{err}: {clip(c, a.tool)}{gap}')

